public Mono<Recommendations> getRecommendations(String userId) {
    return webClient.get()
        .uri("/reco/{id}", userId)
        .retrieve()
        .bodyToMono(Recommendations.class)
        .timeout(Duration.ofSeconds(2))
        .retryWhen(Retry.backoff(3, Duration.ofMillis(100)).jitter(0.5))
        .onErrorResume(ex -> Mono.just(Recommendations.empty()));
}
